from pathlib import Path
root=Path('outputs/ROMDex')
def patch(f,a,b):
 p=root/f;s=p.read_text(encoding='utf-8')
 if b in s:return
 assert a in s,(f,a[:80]);p.write_text(s.replace(a,b,1),encoding='utf-8',newline='\n')
